const me = $('Instagram Hesabı Doğrula').first()?.json || {};
const igUserId = String(me.user_id || me.id || '').trim();
if (!igUserId) {
  throw new Error('Instagram hesabı doğrulanamadı. Token veya hesap türünü kontrol edin.');
}

const recentRaw = $('Son Paylaşımları Çek').first()?.json || {};
const recentPosts = Array.isArray(recentRaw.data) ? recentRaw.data : [];

const ghRaw = $input.first()?.json || {};
let posts = [];
try {
  const parsed = typeof ghRaw === 'string' ? JSON.parse(ghRaw) : (typeof ghRaw.data === 'string' ? JSON.parse(ghRaw.data) : ghRaw);
  if (Array.isArray(parsed.posts)) posts = parsed.posts;
} catch {}

if (posts.length === 0) return [];

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (!Array.isArray(sd.sentHistory)) sd.sentHistory = [];
sd.lastPublishedAt = Number(sd.lastPublishedAt || 0);

const nowSec = Math.floor(Date.now() / 1000);
const trtNow = new Date((nowSec + 3 * 3600) * 1000);
const todayTrt = trtNow.toISOString().slice(0, 10);
const hourTrt = trtNow.getUTCHours();

let execMode = 'trigger';
try { if (typeof $execution !== 'undefined' && $execution.mode) execMode = String($execution.mode); } catch {}
try { if (typeof $('Manuel Tetikle') !== 'undefined' && $('Manuel Tetikle').isExecuted) execMode = 'manual'; } catch {}
const isManual = execMode === 'manual';

let latestLiveTs = 0;
let liveTodayCount = 0;
const liveCaptions = [];
for (const m of recentPosts) {
  if (m.caption) liveCaptions.push(String(m.caption).toLowerCase().trim());
  if (m.timestamp) {
    const ts = Math.floor(Date.parse(m.timestamp) / 1000);
    if (Number.isFinite(ts) && ts > 0) {
      if (ts > latestLiveTs) latestLiveTs = ts;
      const dStr = new Date((ts + 3 * 3600) * 1000).toISOString().slice(0, 10);
      if (dStr === todayTrt) liveTodayCount += 1;
    }
  }
}

if (!isManual) {
  if (hourTrt < 13 || hourTrt > 21) return [];
  const effectiveLast = Math.max(sd.lastPublishedAt, latestLiveTs);
  if (liveTodayCount >= 1) return [];
  if (effectiveLast && (nowSec - effectiveLast < 20 * 3600)) return [];
  const dayNum = Number(todayTrt.replace(/-/g, ''));
  const targetHour = 14 + (dayNum % 7);
  if (hourTrt < targetHour) return [];
}

const sentSet = new Set(sd.sentIds);
const candidate = posts.find((p) => {
  if (!p || !p.id || !p.caption) return false;
  if (sentSet.has(p.id)) return false;
  const mt = String(p.media_type || 'IMAGE').toUpperCase();
  if (mt === 'REELS') {
    if (!/^https:\/\//i.test(p.video_url || '') || !/\.mp4(?:\?|$)/i.test(p.video_url || '')) return false;
  } else if (mt === 'CAROUSEL') {
    if (!Array.isArray(p.slides) || p.slides.length < 2) return false;
    if (!p.slides.every((u) => /^https:\/\//i.test(u) && /\.jpe?g(?:\?|$)/i.test(u))) return false;
  } else {
    if (!/^https:\/\//i.test(p.image_url || '') || !/\.jpe?g(?:\?|$)/i.test(p.image_url || '')) return false;
  }
  const firstLine = String(p.caption).split('\n')[0].toLowerCase().trim();
  if (firstLine.length >= 20 && liveCaptions.some((c) => c.includes(firstLine))) return false;
  return true;
});

if (!candidate) return [];

const mediaType = String(candidate.media_type || 'IMAGE').toUpperCase();
const coverUrl = mediaType === 'REELS'
  ? (candidate.cover_url || candidate.video_url.replace(/\.mp4(?:\?.*)?$/i, '_cover.jpg'))
  : null;

return [{
  json: {
    igUserId,
    username: String(me.username || 'socialora1'),
    postId: candidate.id,
    mediaType,
    videoUrl: candidate.video_url || null,
    coverUrl,
    slides: Array.isArray(candidate.slides) ? candidate.slides : null,
    imageUrl: candidate.image_url || null,
    caption: candidate.caption,
    nowSec,
    pollAttempt: 0
  }
}];

const res = $input.first()?.json || {};
const code = String(res.status_code || '').toUpperCase();
if (code === 'ERROR' || code === 'EXPIRED') {
  throw new Error('Instagram Reels konteyner hatası: ' + JSON.stringify(res));
}
const sd = $getWorkflowStaticData('global');
const creationId = String(res.id || $('Reels Konteyneri Oluştur').first().json.id);
const key = 'poll_' + creationId;
sd[key] = Number(sd[key] || 0) + 1;
const ready = code === 'FINISHED';
if (ready || sd[key] >= 6) {
  delete sd[key];
}
return [{ json: { id: creationId, status_code: code, ready, attempt: sd[key] || 6 } }];

const picked = $('İçerik Seç & Tekrar Kontrolü').first().json;
return (picked.slides || []).map((slideUrl) => ({
  json: {
    igUserId: picked.igUserId,
    slideUrl,
    caption: picked.caption
  }
}));

const picked = $('İçerik Seç & Tekrar Kontrolü').first().json;
const children = $input.all().map((item) => item.json?.id).filter(Boolean);
if (children.length < 2) {
  throw new Error('Carousel çocuk konteynerleri oluşturulamadı.');
}
return [{ json: { igUserId: picked.igUserId, children, caption: picked.caption } }];

const picked = $('İçerik Seç & Tekrar Kontrolü').first().json;
const published = $input.first()?.json || {};
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (!Array.isArray(sd.sentHistory)) sd.sentHistory = [];
if (!sd.sentIds.includes(picked.postId)) sd.sentIds.push(picked.postId);
sd.lastPublishedAt = Math.floor(Date.now() / 1000);
sd.sentHistory.push({
  postId: picked.postId,
  mediaType: picked.mediaType,
  igMediaId: String(published.id || ''),
  sentAt: sd.lastPublishedAt
});
sd.sentHistory = sd.sentHistory.slice(-50);
return [{ json: { ok: true, postId: picked.postId, mediaType: picked.mediaType, igMediaId: published.id || null, username: picked.username } }];
